// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency) public {
        // Record configured state before the call
        bool configuredBefore = c.configured();

        // Call assertGovernanceApproved (underlying flashEnabled requires msg.sender == DAO or governed[msg.sender])
        // Since we're DAO (this contract in setUp), the call proceeds
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // Assert that configured remains unchanged
        bool configuredAfter = c.configured();
        assertTrue(configuredBefore == configuredAfter, "configured should not change");
    }
}

