pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure the sender is either DAO or governed
        vm.assume(sender == c.DAO() || c.governed(sender));

        // Ensure the reference contract can actually perform the transfer
        // We need a token that c owns enough of; use a simple mock if needed
        // But to keep it simple, we assume the flashGovernanceConfig is set up correctly
        // This test will only work if flashGovernanceConfig.asset has enough balance
        // For simplicity, we restrict to cases where the config is already set
        vm.assume(c.flashGovernanceConfig().amount > 0);
        vm.assume(c.flashGovernanceConfig().unlockTime > 0);

        // Prepare: fund c with the asset if needed? Not necessary for this property.

        // Call assertGovernanceApproved – it may revert, but we’re interested in state after if it succeeds
        // We’ll use a try/catch to handle reverts
        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The key property: configured must be true after the call (reference always satisfies)
        // The bug sets configured = false, breaking this property
        assertTrue(c.configured() == true, "configured should be true");
    }
}

