pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, address target, bool emergency, address governanceAsset) public {
        // Bound the governance asset to avoid unrealistic values
        vm.assume(governanceAsset != address(0));
        uint256 amount = 100;
        uint256 unlockTime = 1 hours;

        // Set up the flash governance config so that assertGovernanceApproved can proceed
        // We need to impersonate a successful proposal to configure flash governance
        vm.prank(address(this)); // DAO initially
        c.configureFlashGovernance(governanceAsset, amount, unlockTime, false);

        // Ensure caller is NOT the DAO and NOT governed
        vm.assume(caller != address(this) && !c.governed(caller));

        // Track governer before call
        address governerBefore;
        // Access governer directly as it's public (inherited from Governable)
        governerBefore = address(c.governer());

        // Call assertGovernanceApproved - this will likely revert because caller has no authority
        // But we need to check the state after even if it reverts
        if (caller != address(this) && !c.governed(caller)) {
            // The call should revert since the caller is not authorized
            vm.prank(caller);
            // This will revert with "LIMBO: EP"
            // We only care about state after the call - the governer should stay as is
            vm.expectRevert();
            c.assertGovernanceApproved(caller, target, emergency);
        }

        // General rule: After any call from a non-governed/non-DAO address, 
        // governer must not have been set if it was zero before
        // In the reference, setDAO deletes governer, so it should stay zero
        // In the mutant, setDAO does NOT delete governer, so it may be set by flashGoverner()
        // The key difference: If governer was zero, after the failed call it stays zero in P, 
        // but in M it might be set during assertGovernanceApproved

        // For non-DAO/non-governed callers, the call reverts before setting governer
        // So governer should remain the same
        address governerAfter = address(c.governer());
        assertTrue(governerAfter == governerBefore, "Governer changed after failed call");
    }
}

