pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure sender is not the zero address to avoid trivial cases
        vm.assume(sender != address(0));

        // Record the governer address before the call
        address governerBefore;
        // governer is a public variable in Governable (FlashGovernanceArbiterLike public governer)
        try c.governer() {
            governerBefore = c.governer();
        } catch {
            governerBefore = address(0);
        }

        // Determine if sender is governed or the DAO
        bool isGoverned = sender == address(c.DAO()) || c.governed(sender);

        // Make the call
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // Check the rule
        address governerAfter = c.governer();
        bool ruleViolated = (governerBefore == address(0) && governerAfter != address(0) && !isGoverned);
        assertTrue(!ruleViolated, "governer became non-zero after call from non-governed/non-DAO sender");
    }
}

