pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency, address randomAddr) public {
        // Ensure randomAddr is not in the governables array (here we use an empty array so any address qualifies)
        vm.assume(randomAddr != address(0));

        // Prepare empty governables and isGoverned arrays so that no address is changed
        address[] memory governables = new address[](0);
        bool[] memory isGoverned = new bool[](0);

        // Use onlySuccessfulProposal modifier, so we need the DAO to be a successful proposal
        // Since we deployed with address(this) as DAO, we must make a successful proposal ourselves.
        // We simulate that by using vm.prank to set msg.sender as a successful proposal.
        // However, without a real DAO, we can cheat: set DAO to this contract and override successfulProposal?
        // Simpler: we cannot call setGoverned() because it requires a successful proposal.
        // But the mutation only affects setGoverned. So we can directly manipulate the governed mapping?
        // No, we cannot access private state. But we can call assertGovernanceApproved() which reads governed.
        // We need to set up the DAO and flash governance config first.

        // Since we are the DAO, we can call setGoverned ourselves? Actually onlySuccessfulProposal checks DAO.successfulProposal(sender).
        // To avoid complexity, we skip setGoverned and instead test the assertion by checking governed values after asserting governance.
        // The bug is in setGoverned, so the test must call setGoverned to trigger the bug.
        // We can make the test simpler: after calling setGoverned with empty arrays, governed[randomAddr] should remain false.

        // Record initial governed status of randomAddr
        bool initialGoverned = c.governed(randomAddr);

        // We need to make ourselves a successful proposal. We can deploy a mock DAO that returns true for any sender.
        // But we cannot deploy another contract in this test. We can use vm.mockCall to mock successfulProposal.
        address daoAddress = address(this);
        vm.mockCall(
            daoAddress,
            abi.encodeWithSignature("successfulProposal(address)", address(this)),
            abi.encode(true)
        );

        // Set flash governance config so assertGovernanceApproved doesn't revert
        // We need the asset to be set, and we need to provide enough balance
        // Deploy a mock ERC20 if needed? Simpler: we don't need to call assertGovernanceApproved, we can directly test governed.

        // Actually, the bug is in setGoverned. We just need to call that function and then check governed[randomAddr].
        // The onlySuccessfulProposal modifier can be bypassed by mocking the DAO.
        vm.prank(address(this));
        c.setGoverned(governables, isGoverned);

        // After setGoverned with empty arrays, no address should have changed
        assertTrue(c.governed(randomAddr) == initialGoverned, "Governed status should remain unchanged for addresses not in governables");
    }
}

