pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency, address[] calldata governables, bool[] calldata isGoverned) public {
        vm.assume(governables.length == isGoverned.length && governables.length > 0);
        // Prank as the DAO to set up the flash governance config
        vm.prank(address(this));
        c.setGoverned(governables, isGoverned);

        // Record the governed status for each address in governables before the call
        bool[] memory before = new bool[](governables.length);
        for (uint i = 0; i < governables.length; i++) {
            before[i] = c.governed(governables[i]);
        }

        // Call assertGovernanceApproved
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // If the call succeeded, check that governed status for each address matches the intended isGoverned value
        if (success) {
            for (uint i = 0; i < governables.length; i++) {
                bool expected = isGoverned[i];
                assertTrue(c.governed(governables[i]) == expected, "governed status mismatch");
            }
        } else {
            // If it reverted, check that the governed status did not change
            for (uint i = 0; i < governables.length; i++) {
                assertTrue(c.governed(governables[i]) == before[i], "governed status changed after revert");
            }
        }
    }
}

