contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable, uint256 epochSize, uint8 maxGovernanceChangePerEpoch, uint8 changeTolerance, address user, address[] memory governables, bool[] memory isGoverned) public {
        vm.assume(sender != address(0) && target != address(0) && user != address(0));
        vm.assume(governables.length == isGoverned.length && governables.length <= 10);
        for (uint i = 0; i < governables.length; i++) {
            vm.assume(governables[i] != address(0));
        }
        vm.assume(changeTolerance < 100);
        c.setGoverned(governables, isGoverned);
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);
        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);
        c.endConfiguration();
        (,, bool assetBurnableConfig) = c.flashGovernanceConfig();
        vm.assume(assetBurnableConfig == assetBurnable);
        uint256 balanceBefore = address(this).balance;
        uint256 epochSizeBefore = c.security().epochSize;
        uint256 lastFlashBefore = c.security().lastFlashGovernanceAct;
        bool reverted = false;
        try c.assertGovernanceApproved(sender, target, emergency) {
            uint256 lastFlashAfter = c.security().lastFlashGovernanceAct;
            assertTrue(lastFlashAfter >= lastFlashBefore || emergency, "Rule: lastFlashGovernanceAct only updates on non-emergency");
        } catch {
            reverted = true;
        }
        if (!reverted) {
            uint256 lastFlashAfter = c.security().lastFlashGovernanceAct;
            assertTrue(lastFlashAfter == block.timestamp, "Rule: lastFlashGovernanceAct set to block.timestamp");
        }
    }
}

